  const blockers=(value=[])=>rows(value).map(x=>typeof x==='string'?x:x?._key||x?.code||String(x));
  const linkBlockers=Array.isArray(link.blockers)?link.blockers:[],reverseBlockers=Array.isArray(reverse.blockers)?reverse.blockers:[];
  const disabled=attrDisabled(readOnly),readonlyAction=readOnly?' data-v33-readonly-action="true"':'',qaNote=readOnly?'<div class="sj-v33-fin-alert warn">LOCAL QA · aksi rekonsiliasi ditampilkan untuk audit tetapi dinonaktifkan.</div>':'';
  const dryStatus=String(dry.status||'UNKNOWN'),dryRunCard=dry.status?`<section class="sj-v33-fin-close-card"><div class="sj-v33-fin-subhead"><div><b>Dry-run Link Expense</b><small>Read-only · preview sebelum writer dijalankan</small></div><span>${esc(dryStatus)}</span></div><div class="sj-v33-purchase-audit-grid"><span>Target Shift<b>${esc(dry.target?.shiftKey||'Belum tersedia')}</b></span><span>Expense ID<b>${esc(dry.target?.expenseRef||'Belum tersedia')}</b></span><span>Status Target<b>${esc(dryStatus)}</b></span><span>Repair<b>${dry.canRepair?'Eligible':'Tidak diperlukan / diblokir'}</b></span><span>Preview Kategori<b>${esc(dry.preview?.category||'-')}</b></span><span>Preview Nama<b>${esc(dry.preview?.name||'-')}</b></span><span>Preview Nilai<b>${money(dry.preview?.amount||0)}</b></span><span>Preview Source<b>${esc(dry.preview?.source||'-')}</b></span><span>Supplier<b>${esc(dry.preview?.supplier||'-')}</b></span><span>Purchase Ref<b>${esc(dry.preview?.purchaseRef||'-')}</b></span><span>System Linked<b>${dry.preview?.systemLinked?'Ya':'Tidak'}</b></span></div>${dryStatus==='MISSING'?'<div class="sj-v33-fin-alert ok">Target expense kosong. LINK_REPAIR dapat memulihkan evidence tanpa mengubah purchase.</div>':dryStatus==='OCCUPIED_MISMATCH'?'<div class="sj-v33-fin-alert warn">Expense ID ditempati record yang tidak cocok. Writer wajib menolak overwrite.</div>':'<div class="sj-v33-fin-alert ok">Linked expense sudah valid; repair tidak diperlukan.</div>'}</section>`:'';
  const movementClassLabel=value=>({TRANSFER:'Transfer',CONSUMPTION:'Konsumsi',ADJUSTMENT_AMBIGUOUS:'Opname / adjustment ambigu',AMBIGUOUS:'Movement ambigu',INBOUND:'Inbound'}[value]||String(value||'Unknown'));
  const downstreamRows=rows(downstream.movements),downstreamCard=downstream.purchaseId?`<section class="sj-v33-fin-close-card"><div class="sj-v33-fin-subhead"><div><b>Evidence Inventory Setelah Pembelian</b><small>Read-only · menjelaskan blocker reversal</small></div><span>${downstreamRows.length} movement</span></div><div class="sj-v33-purchase-audit-grid"><span>Qty Purchase<b>${num(downstream.purchaseQty)} ${esc(downstream.unit||'unit')}</b></span><span>Nilai Purchase<b>${money(downstream.landedCost)}</b></span><span>Stok Purchase<b>${downstream.stockBefore==null||downstream.stockAfter==null?'Belum lengkap':`${num(downstream.stockBefore)} → ${num(downstream.stockAfter)}`}</b></span><span>Stok Saat Ini<b>Gudang ${num(downstream.currentWarehouse)} · Gerai ${num(downstream.currentOutlet)}</b></span><span>WAC Purchase<b>${downstream.oldWac==null||downstream.newWac==null?'Belum lengkap':`${money(downstream.oldWac)} → ${money(downstream.newWac)}`}</b></span><span>WAC Saat Ini<b>${money(downstream.currentWac)}</b></span><span>Konsumsi Terlihat<b>${num(downstream.consumptiveQty)} ${esc(downstream.unit||'unit')}</b></span><span>Movement Ambigu<b>${num(downstream.ambiguousCount)}</b></span></div>${downstreamRows.length?`<div class="sj-v33-reconcile-history"><b>Movement setelah purchase</b>${downstreamRows.map(x=>`<article><span>${esc(x.type)}</span><strong>${esc(movementClassLabel(x.classification))}</strong><small>${esc(timeLabel(x.ts))} · ${num(x.delta)>0?'+':''}${num(x.delta)} · ${esc(x.location||'-')} · ${esc(x.id||'')}</small></article>`).join('')}</div>`:'<div class="sj-v33-fin-alert ok">Tidak ada movement downstream yang terdeteksi.</div>'}</section>`:'';
