  const fundingCard=funding.treatment?`<section class="sj-v33-fin-close-card"><div class="sj-v33-fin-subhead"><div><b>Funding Semantics</b><small>Sumber dana dipisahkan dari dampak kas usaha</small></div><span>${esc(funding.source||audit.fundSource||'OTHER')}</span></div><div class="sj-v33-purchase-audit-grid"><span>Nilai Purchase<b>${money(funding.amount??audit.landedCost)}</b></span><span>Dampak Arus Kas Usaha<b>${money(funding.confirmedBusinessAmount||0)}</b></span><span>Perlakuan<b>${esc(fundingTreatmentLabel(funding.treatment))}</b></span><span>Perlu authority tambahan<b>${funding.requiresAuthority?'Ya':'Tidak'}</b></span></div>${funding.treatment==='OWNER_DIRECT'?'<div class="sj-v33-fin-alert ok">Dana Owner membiayai persediaan secara langsung; transaksi tetap diaudit tetapi tidak mengurangi kas usaha.</div>':funding.requiresAuthority?'<div class="sj-v33-fin-alert warn">Nilai pembelian tetap terlihat, tetapi belum dimasukkan ke arus kas usaha sampai authority sumber dana tersedia.</div>':''}</section>`:'';
  const wacReasonLabel=code=>({WAC_CHANGED_BY_PURCHASE:'WAC berubah saat purchase',DOWNSTREAM_OPNAME_OR_ADJUSTMENT:'Ada opname/adjustment setelah purchase',DOWNSTREAM_CONSUMPTION_PRESENT:'Ada konsumsi setelah purchase',AUTO_WAC_REWRITE_FORBIDDEN:'Auto WAC rewrite dilarang; review biaya harus manual'}[code]||String(code||''));
  const wacCard=wac.status?`<section class="sj-v33-fin-close-card"><div class="sj-v33-fin-subhead"><div><b>WAC Cost Review</b><small>Read-only · tidak melakukan rewrite valuasi</small></div><span>${esc(wac.status)}</span></div><div class="sj-v33-purchase-audit-grid"><span>WAC Sebelum<b>${wac.oldWac==null?'Belum tersedia':money(wac.oldWac)}</b></span><span>WAC Setelah Purchase<b>${wac.purchaseWac==null?'Belum tersedia':money(wac.purchaseWac)}</b></span><span>WAC Saat Ini<b>${wac.currentWac==null?'Belum tersedia':money(wac.currentWac)}</b></span><span>Auto Rewrite<b>${wac.autoRewriteAllowed?'Diizinkan':'Dilarang'}</b></span></div>${rows(wac.reasonCodes).map(x=>`<div class="sj-v33-fin-alert ${String(x).includes('FORBIDDEN')?'warn':'ok'}">${esc(wacReasonLabel(typeof x==='string'?x:x?._key||x?.code))}</div>`).join('')}</section>`:'';
