  const linkAction=link.eligible?`<form class="sj-v33-reconcile-action" data-v33-purchase-link-repair-form><input type="hidden" name="purchaseId" value="${esc(audit.purchaseId)}"><label><span>Catatan pemulihan</span><input name="note" placeholder="Contoh: pulihkan linked expense"${disabled}></label><label><span>PIN Owner</span><input name="pin" type="password" inputmode="numeric" autocomplete="off"${disabled}></label><button type="submit"${disabled}${readonlyAction}>${readOnly?'🔒 Pulihkan Link Expense · READ ONLY':'Pulihkan Link Expense'}</button></form>`:`<div class="sj-v33-reconcile-blockers"><b>Pulihkan Link Expense belum dapat dilakukan</b>${linkBlockers.map(x=>`<p>${esc(blockerLabel(x))}</p>`).join('')}</div>`;
